**2. JavaScript (Sorting Logic)**

```javascript
document.addEventListener('DOMContentLoaded', function() {
  const table = document.querySelector('.table');
  const headers = table.querySelectorAll('th');
  const tbody = table.querySelector('tbody');
  let currentSortColumn = null;
  let sortOrder = 1; // 1 = ascending, -1 = descending

  headers.forEach(header => {
    header.addEventListener('click', function() {
      const sortType = this.dataset.sort;
      const columnIndex = Array.from(headers).indexOf(this);

      if (columnIndex === currentSortColumn) {
        sortOrder *= -1; // Toggle sort order
      } else {
        currentSortColumn = columnIndex;
        sortOrder = 1;
      }

      const rows = Array.from(tbody.querySelectorAll('tr'));

      rows.sort((rowA, rowB) => {
        const cellA = rowA.querySelectorAll('td')[columnIndex].textContent;
        const cellB = rowB.querySelectorAll('td')[columnIndex].textContent;

        let comparison = 0;

        switch (sortType) {
          case 'string':
            comparison = cellA.localeCompare(cellB);
            break;
          case 'number':
            comparison = parseFloat(cellA) - parseFloat(cellB);
            break;
          case 'date':
            comparison = new Date(cellA) - new Date(cellB);
            break;
          default:
            comparison = cellA.localeCompare(cellB); // Default to string
        }

        return comparison * sortOrder;
      });

      // Clear the table and re-append the sorted rows
      tbody.innerHTML = '';
      rows.forEach(row => tbody.appendChild(row));
    });
  });
});
```

**Explanation of the JavaScript:**

1.  **`DOMContentLoaded`**:  Ensures the script runs after the HTML is fully loaded.
2.  **`table`, `headers`, `tbody`**:  Selects the table, header cells, and table body elements.

